class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        ListNode slow = head;
        ListNode fast = head.next;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode mid = slow.next;
        slow.next = null;

        ListNode left = sortList(head);
        ListNode right = sortList(mid);
        return merge(left, right);
    }

    private ListNode merge(ListNode left, ListNode right) {
        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (left != null && right != null) {
            if (left.val <= right.val) {
                tail.next = left;
                left = left.next;
            } else {
                tail.next = right;
                right = right.next;
            }
            tail = tail.next;
        }
        tail.next = (left != null) ? left : right;
        return dummy.next;
    }
}

class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        int length = 0;
        ListNode curr = head;
        while (curr != null) {
            length++;
            curr = curr.next;
        }

        ListNode dummy = new ListNode(0, head);
        for (int size = 1; size < length; size *= 2) {
            ListNode prev = dummy;
            curr = dummy.next;
            while (curr != null) {
                ListNode left = curr;
                ListNode right = split(left, size);
                curr = split(right, size);
                prev = merge(left, right, prev);
            }
        }
        return dummy.next;
    }

    private ListNode split(ListNode head, int size) {
        for (int i = 1; head != null && i < size; i++) {
            head = head.next;
        }
        if (head == null) return null;
        ListNode next = head.next;
        head.next = null;
        return next;
    }

    private ListNode merge(ListNode left, ListNode right, ListNode prev) {
        while (left != null && right != null) {
            if (left.val <= right.val) {
                prev.next = left;
                left = left.next;
            } else {
                prev.next = right;
                right = right.next;
            }
            prev = prev.next;
        }
        prev.next = (left != null) ? left : right;
        while (prev.next != null) {
            prev = prev.next;
        }
        return prev;
    }
}

import java.util.*;

class Solution {
    public ListNode sortList(ListNode head) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> Integer.compare(a.val, b.val));
        while (head != null) {
            ListNode next = head.next;
            head.next = null;
            heap.offer(head);
            head = next;
        }

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        while (!heap.isEmpty()) {
            tail.next = heap.poll();
            tail = tail.next;
            tail.next = null;
        }
        return dummy.next;
    }
}

class Solution {
    private static final int OFFSET = 100000;
    private static final int RANGE = 200001;

    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;

        int[] counts = new int[RANGE];
        ListNode curr = head;
        while (curr != null) {
            counts[curr.val + OFFSET]++;
            curr = curr.next;
        }

        curr = head;
        for (int value = -OFFSET; value <= OFFSET; value++) {
            int count = counts[value + OFFSET];
            while (count-- > 0) {
                curr.val = value;
                curr = curr.next;
            }
        }
        return head;
    }
}
